INSERT INTO `ai_playerbot_texts` (`name`, `text`, `say_type`, `reply_type`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`) VALUES
('string_cant_change_strategy',   'You can change any strategy except loot and gather', 0, 0, '', 'Vous pouvez changer toute stratégie sauf loot et collecte.', 'Du kannst jede Strategie außer Looten und Sammeln ändern.', '你可以更改除拾取和采集之外的任何策略。', '', 'Puedes cambiar cualquier estrategia excepto saqueo y recolección.', '', 'Можно изменить любую стратегию кроме лута и сбора.'),
('string_no_rti_target',          'I dont see my rti attack target',                   0, 0, '', 'Je ne vois pas ma cible RTI.', 'Ich sehe mein RTI-Angriffsziel nicht.', '我看不到RTI攻击目标。', '', 'No veo mi objetivo de ataque RTI.', '', 'Не вижу цели для атаки по RTI.'),
('string_too_far_go',             'It is too far away',                                0, 0, '', 'C\'est trop loin.', 'Es ist zu weit weg.', '太远了。', '', 'Está demasiado lejos.', '', 'Слишком далеко.'),
('string_in_water',               'It is in water',                                    0, 0, '', 'C\'est dans l\'eau.', 'Es ist im Wasser.', '在水里。', '', 'Está en el agua.', '', 'Это в воде.'),
('string_cant_go_there',          'I can\'t go there',                                 0, 0, '', 'Je ne peux pas y aller.', 'Ich kann nicht dorthin gehen.', '我去不了那里。', '', 'No puedo ir allí.', '', 'Не могу туда идти.'),
('string_unknown_gossip',         'Unknown gossip option',                             0, 0, '', 'Option de dialogue inconnue.', 'Unbekannte Gossip-Option.', '未知对话选项。', '', 'Opción de diálogo desconocida.', '', 'Неизвестный вариант диалога.'),
('string_need_talk_first',        'I need to talk first',                              0, 0, '', 'Je dois d\'abord parler.', 'Ich muss erst reden.', '我需要先对话。', '', 'Necesito hablar primero.', '', 'Сначала нужно поговорить.'),
('string_happy_in_guild',         'Sorry, I am happy in my guild :)',                  0, 0, '', 'Désolé, je suis heureux dans ma guilde :)', 'Entschuldigung, ich bin glücklich in meiner Gilde :)', '抱歉，我在公会里很开心 :)', '', 'Lo siento, estoy feliz en mi hermandad :)', '', 'Извини, я доволен своей гильдией :)'),
('string_not_enough_bag_space',   'Not enough bag space',                              0, 0, '', 'Pas assez de place dans les sacs.', 'Nicht genug Taschenplatz.', '背包空间不足。', '', 'Espacio de bolsa insuficiente.', '', 'Недостаточно места в сумке.'),
('string_no_mailbox',             'There is no mailbox nearby',                        0, 0, '', 'Il n\'y a pas de boîte aux lettres à proximité.', 'Kein Briefkasten in der Nähe.', '附近没有邮箱。', '', 'No hay buzón de correo cerca.', '', 'Поблизости нет почтового ящика.'),
('string_all_paths_no_los',       'All paths not in LOS',                              0, 0, '', 'Tous les chemins hors ligne de vue.', 'Alle Wege außer Sichtlinie.', '所有路径都不在视线范围内。', '', 'Todos los caminos fuera de línea de visión.', '', 'Все пути вне зоны видимости.'),
('string_stuck_following',        'I am stuck while following',                        0, 0, '', 'Je suis bloqué en suivant.', 'Ich stecke beim Folgen fest.', '我在跟随时被卡住了。', '', 'Estoy atascado mientras sigo.', '', 'Застрял во время следования.'),
('string_stuck_fleeing',          'I am stuck while fleeing',                          0, 0, '', 'Je suis bloqué en fuyant.', 'Ich stecke auf der Flucht fest.', '我在逃跑时被卡住了。', '', 'Estoy atascado mientras huyo.', '', 'Застрял во время бегства.'),
('string_nowhere_to_flee',        'Nowhere to flee',                                   0, 0, '', 'Nulle part où fuir.', 'Nirgendwo hinzufliehen.', '无处可逃。', '', 'No hay donde huir.', '', 'Некуда бежать.'),
('string_already_in_team',        'Sorry, I am already in such team',                  0, 0, '', 'Désolé, je suis déjà dans cette équipe.', 'Entschuldigung, ich bin bereits in so einem Team.', '抱歉，我已经在这个队伍里了。', '', 'Lo siento, ya estoy en ese equipo.', '', 'Извини, я уже в такой команде.'),
('string_already_in_guild',       'Sorry, I am in a guild already',                   0, 0, '', 'Désolé, je suis déjà dans une guilde.', 'Entschuldigung, ich bin bereits in einer Gilde.', '抱歉，我已经在一个公会里了。', '', 'Lo siento, ya estoy en una hermandad.', '', 'Извини, я уже в гильдии.'),
('string_already_invited_guild',  'Sorry, I am invited to a guild already',            0, 0, '', 'Désolé, j\'ai déjà une invitation de guilde.', 'Entschuldigung, ich habe bereits eine Gildeneinladung.', '抱歉，我已经被邀请加入公会了。', '', 'Lo siento, ya tengo una invitación a hermandad.', '', 'Извини, меня уже пригласили в гильдию.'),
('string_already_signed_petition','Sorry, I already signed this pettition',            0, 0, '', 'Désolé, j\'ai déjà signé cette pétition.', 'Entschuldigung, ich habe diese Petition bereits unterschrieben.', '抱歉，我已经在这份请愿书上签名了。', '', 'Lo siento, ya firmé esta petición.', '', 'Извини, я уже подписал эту петицию.'),
('string_out_of_ammo',            'Out of ammo!',                                      0, 0, '', 'Plus de munitions!', 'Keine Munition mehr!', '弹药耗尽！', '', '¡Sin munición!', '', 'Боеприпасы кончились!'),
('string_no_pet',                 'No pet!',                                           0, 0, '', 'Pas de familier!', 'Kein Haustier!', '没有宠物！', '', '¡Sin mascota!', '', 'Нет питомца!'),
('string_pet_unhappy',            'Pet is unhappy!',                                   0, 0, '', 'Le familier est malheureux!', 'Das Haustier ist unglücklich!', '宠物不高兴！', '', '¡La mascota está triste!', '', 'Питомец недоволен!'),
('string_no_repair_npc',          'Cannot find any npc to repair at',                  0, 0, '', 'Impossible de trouver un PNJ pour réparer.', 'Kann keinen NPC zum Reparieren finden.', '找不到可以修理的NPC。', '', 'No se puede encontrar un PNJ para reparar.', '', 'Не найти НПС для починки.'),
('string_not_a_spirit',           'I am not a spirit',                                 0, 0, '', 'Je ne suis pas un esprit.', 'Ich bin kein Geist.', '我不是灵魂。', '', 'No soy un espíritu.', '', 'Я не призрак.'),
('string_cant_talk_quest_giver',  'Cannot talk to quest giver',                        0, 0, '', 'Impossible de parler au donneur de quête.', 'Kann nicht mit dem Questgeber sprechen.', '无法与任务发布者交谈。', '', 'No se puede hablar con el dador de misiones.', '', 'Не могу поговорить с квестодателем.'),
('string_guild_loot_only',        'I will play with this loot type only if I\'m in your guild :/', 0, 0, '', 'Je jouerai avec ce type de butin seulement si je suis dans ta guilde :/', 'Ich spiele mit diesem Beutesystem nur, wenn ich in deiner Gilde bin :/', '只有在你的公会里我才会用这种拾取方式 :/', '', 'Solo jugaré con este tipo de botín si estoy en tu hermandad :/', '', 'Буду играть с этим типом лута только если я в твоей гильдии :/'),
('string_unknown_spell',          'Unknown spell',                                     0, 0, '', 'Sort inconnu.', 'Unbekannter Zauber.', '未知法术。', '', 'Hechizo desconocido.', '', 'Неизвестное заклинание.'),
('string_no_portal',              'Cannot find any portal to teleport',                0, 0, '', 'Impossible de trouver un portail.', 'Kein Portal zum Teleportieren gefunden.', '找不到传送门。', '', 'No se puede encontrar ningún portal.', '', 'Не найти портал для телепорта.'),
('string_glyphs_prefix',          'Glyphs: ',                                          0, 0, '', 'Glyphes: ', 'Glyphen: ', '雕文：', '', 'Glifos: ', '', 'Глифы: '),
('string_max_wait_time',          'Max wait time is 20 seconds!',                      0, 0, '', 'Le temps d\'attente maximum est de 20 secondes!', 'Maximale Wartezeit beträgt 20 Sekunden!', '最大等待时间为20秒！', '', '¡El tiempo de espera máximo es de 20 segundos!', '', 'Максимальное время ожидания — 20 секунд!'),
('string_failed_pick_lock',       'Failed to cast Pick Lock.',                         0, 0, '', 'Échec du lancement de Crochetage.', 'Schlossknacken fehlgeschlagen.', '施放开锁失败。', '', 'Fallo al lanzar Abrir cerradura.', '', 'Не удалось применить Взлом замка.'),
('string_no_item_trade_slot',     'No item in the Do Not Trade slot.',                 0, 0, '', 'Aucun objet dans le slot Ne pas échanger.', 'Kein Gegenstand im Nicht-Handeln-Slot.', '不交易槽中没有物品。', '', 'No hay objeto en la ranura No comerciar.', '', 'В слоте "Не торговать" нет предмета.'),
('string_cant_unlock_trade',      'Cannot unlock this item.',                          0, 0, '', 'Impossible de déverrouiller cet objet.', 'Kann diesen Gegenstand nicht entsperren.', '无法解锁此物品。', '', 'No se puede desbloquear este objeto.', '', 'Невозможно разблокировать этот предмет.'),
('string_no_pick_lock_spell',     'Cannot unlock, Pick Lock spell is missing.',        0, 0, '', 'Impossible de déverrouiller, sort Crochetage manquant.', 'Kann nicht entsperren, Schlossknacken-Zauber fehlt.', '无法解锁，缺少开锁技能。', '', 'No se puede desbloquear, falta el hechizo.', '', 'Нельзя разблокировать — нет заклинания Взлом замка.'),
('string_ignored_far_from_master','%unit ignored (far from master).',                  0, 0, '', '%unit ignoré (trop loin du maître).', '%unit ignoriert (zu weit vom Meister).', '%unit被忽略（远离主人）。', '', '%unit ignorado (lejos del maestro).', '', '%unit проигнорирован (далеко от хозяина).'),
('string_maintenance_not_allowed','maintenance command is not allowed, please check the configuration.', 0, 0, '', 'Commande de maintenance non autorisée.', 'Wartungsbefehl nicht erlaubt.', '维护命令不允许。', '', 'Comando de mantenimiento no permitido.', '', 'Команда обслуживания недоступна, проверьте конфигурацию.'),
('string_autogear_not_allowed',   'autogear command is not allowed, please check the configuration.', 0, 0, '', 'Commande autogear non autorisée.', 'Autogear-Befehl nicht erlaubt.', '自动装备命令不允许。', '', 'Comando autogear no permitido.', '', 'Команда автоэкипировки недоступна, проверьте конфигурацию.'),
('string_no_autogear_alt',        'You cannot use autogear on alt bots.',              0, 0, '', 'Vous ne pouvez pas utiliser autogear sur les bots alternatifs.', 'Du kannst Autogear nicht auf Alt-Bots verwenden.', '你不能对小号机器人使用自动装备。', '', 'No puedes usar autogear en bots alternativos.', '', 'Нельзя использовать автоэкипировку на альт-ботах.');
